class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.sma200 = self.SMA(self.spy, 200, Resolution.Daily)
        self.sma50 = self.SMA(self.spy, 50, Resolution.Daily)
        self.rsi14 = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(200, Resolution.Daily)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.previous_spy_close = None
        self.previous_sma200 = None
        self.previous_sma50 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        current_spy_close = None
        current_sma200 = None
        current_sma50 = None
        current_aapl_rsi = None

        if self.spy in data.Bars:
            current_spy_close = float(data.Bars[self.spy].Close)

            if self.sma200.IsReady:
                current_sma200 = float(self.sma200.Current.Value)

            if self.sma50.IsReady:
                current_sma50 = float(self.sma50.Current.Value)

        if self.aapl in data.Bars:
            current_aapl_close = float(data.Bars[self.aapl].Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif current_aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = current_aapl_close

            if self.rsi14.IsReady:
                current_aapl_rsi = float(self.rsi14.Current.Value)

        if not self.IsWarmingUp:
            required_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]
            all_bars_present = all(symbol in data.Bars for symbol in required_symbols)

            indicators_ready = (
                self.sma200.IsReady
                and self.sma50.IsReady
                and self.rsi14.IsReady
                and current_spy_close is not None
                and current_sma200 is not None
                and current_sma50 is not None
                and current_aapl_rsi is not None
                and self.previous_spy_close is not None
                and self.previous_sma200 is not None
                and self.previous_sma50 is not None
            )

            if all_bars_present and indicators_ready:
                strategy_a_buy = (
                    self.previous_spy_close <= self.previous_sma200
                    and current_spy_close > current_sma200
                )

                strategy_a_sell = (
                    self.previous_spy_close >= self.previous_sma50
                    and current_spy_close < current_sma50
                )

                strategy_b_buy = self.aapl_red_streak >= 3
                strategy_b_sell = current_aapl_rsi > 60.0

                if self.strategy_a_shares > 0 and strategy_a_sell:
                    ticket = self.MarketOrder(
                        self.spy,
                        -self.strategy_a_shares
                    )
                    if ticket is not None and ticket.Status != OrderStatus.Invalid:
                        self.strategy_a_shares = 0

                if self.strategy_b_shares > 0 and strategy_b_sell:
                    ticket = self.MarketOrder(
                        self.aapl,
                        -self.strategy_b_shares
                    )
                    if ticket is not None and ticket.Status != OrderStatus.Invalid:
                        self.strategy_b_shares = 0

                if self.strategy_a_shares == 0 and strategy_a_buy:
                    portfolio_value = float(self.Portfolio.TotalPortfolioValue)
                    quantity = int((0.40 * portfolio_value) / current_spy_close)

                    if quantity > 0:
                        ticket = self.MarketOrder(self.spy, quantity)
                        if ticket is not None and ticket.Status != OrderStatus.Invalid:
                            self.strategy_a_shares = quantity

                if self.strategy_b_shares == 0 and strategy_b_buy:
                    available_cash = float(self.Portfolio.Cash)

                    if available_cash >= 20000.0:
                        quantity = int(20000.0 / float(data.Bars[self.aapl].Close))

                        if quantity > 0:
                            ticket = self.MarketOrder(self.aapl, quantity)
                            if ticket is not None and ticket.Status != OrderStatus.Invalid:
                                self.strategy_b_shares = quantity

        if current_spy_close is not None:
            self.previous_spy_close = current_spy_close

        if current_sma200 is not None:
            self.previous_sma200 = current_sma200

        if current_sma50 is not None:
            self.previous_sma50 = current_sma50

