                            + int(order_event.FillQuantity)
                        )

                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.strategy_a_pending = None

        elif order_event.Symbol == self.aapl:
            pending = self.strategy_b_pending
            if pending is not None and pending[0] == order_event.OrderId:
                if order_event.FillQuantity != 0:
                    if pending[1] == "buy":
                        self.strategy_b_lot += int(order_event.FillQuantity)
                    else:
                        self.strategy_b_lot = max(
                            0,
                            self.strategy_b_lot
                            + int(order_event.FillQuantity)
                        )

                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.strategy_b_pending = None
